<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Global Water Stress Convergence</title>
  <style>
    :root {
      --bg: #f8fafc; /* slate-50 */
      --surface: #ffffff;
      --border: #e2e8f0; /* slate-200 */
      --text: #0f172a; /* slate-900 */
      --text-dim: #64748b; /* slate-500 */

      --accent-danger: #be123c; /* rose-700 */
      --accent-warn: #d97706; /* amber-600 */
      --accent-safe: #0369a1; /* sky-700 */
      --accent-safe-dim: rgba(3, 105, 161, 0.1);

      --font-body: 'IBM Plex Sans', system-ui, sans-serif;
      --font-mono: 'IBM Plex Mono', monospace;
    }

    @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&display=swap');

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      background-color: var(--bg);
      color: var(--text);
      font-family: var(--font-body);
      padding: 40px;
      width: 1200px;
      /* Fixed width/height for consistent rendering to PNG */
    }

    .container {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 32px;
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03);
    }

    header { margin-bottom: 24px; border-bottom: 2px solid var(--border); padding-bottom: 16px; }
    h1 { font-size: 24px; font-weight: 600; margin-bottom: 8px; color: var(--text); letter-spacing: -0.5px; }
    p.subtitle { color: var(--text-dim); font-size: 14px; max-width: 800px; line-height: 1.5; }

    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;
      text-align: left;
    }

    th {
      font-weight: 500;
      color: var(--text-dim);
      padding: 12px 8px;
      border-bottom: 1px solid var(--border);
      white-space: nowrap;
      vertical-align: bottom;
      font-family: var(--font-body);
    }

    td {
      padding: 12px 8px;
      border-bottom: 1px solid var(--border);
      vertical-align: middle;
      font-family: var(--font-mono);
      font-size: 13px;
    }

    tr:nth-child(even) td { background-color: rgba(0,0,0,0.02); }

    .country-col { width: 15%; font-family: var(--font-body); font-weight: 500; }
    .ratio-col { width: 25%; }
    .gw-col { width: 20%; }
    .pc-col { width: 20%; }
    .precip-col { width: 20%; }

    .stress-badge {
      display: inline-block;
      padding: 2px 6px;
      border-radius: 4px;
      font-size: 10px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-left: 8px;
      font-family: var(--font-body);
    }
    .badge-eh { background: rgba(190, 18, 60, 0.1); color: var(--accent-danger); }
    .badge-h { background: rgba(217, 119, 6, 0.1); color: var(--accent-warn); }
    .badge-m { background: rgba(100, 116, 139, 0.1); color: var(--text-dim); }
    .badge-l { background: var(--accent-safe-dim); color: var(--accent-safe); }

    /* Visualizations */
    .bar-chart {
      position: relative;
      height: 16px;
      width: 100%;
      background: #f1f5f9;
      border-radius: 2px;
      overflow: hidden;
      display: flex;
      align-items: center;
    }

    .bar-fill {
      height: 100%;
      transition: width 0.3s;
    }

    .gw-danger { color: var(--accent-danger); font-weight: 600; }

    .sparkline {
      width: 100%;
      height: 24px;
    }

    polyline {
      fill: none;
      stroke-width: 2;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    .axis-line {
      position: absolute;
      top: 0;
      bottom: 0;
      width: 1px;
      background: var(--text-dim);
      z-index: 10;
    }

    .axis-label {
      font-size: 10px;
      color: var(--text-dim);
      font-family: var(--font-mono);
      position: absolute;
      top: -18px;
      transform: translateX(-50%);
    }

    .ratio-container, .gw-container {
      position: relative;
      width: 100%;
      height: 12px;
    }

    .ratio-dot {
      position: absolute;
      top: 50%;
      transform: translate(-50%, -50%);
      width: 8px;
      height: 8px;
      border-radius: 50%;
      z-index: 20;
    }

    .gw-bar {
      position: absolute;
      top: 0;
      left: 0;
      height: 100%;
      border-radius: 0 2px 2px 0;
    }

    .val-text {
      display: inline-block;
      width: 45px;
      text-align: right;
      margin-right: 8px;
    }

    .flex-cell {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .legend {
      display: flex;
      gap: 16px;
      margin-top: 16px;
      font-size: 11px;
      font-family: var(--font-body);
      color: var(--text-dim);
    }
    .legend-item { display: flex; align-items: center; gap: 4px; }
    .legend-box { width: 10px; height: 10px; border-radius: 2px; }
  </style>
</head>
<body>
  <div class="container">
    <header>
      <h1>Multi-Indicator Global Water Stress Convergence (2023)</h1>
      <p class="subtitle">An analytical comparison of 10 countries revealing severe compounding factors in arid regions, where extreme supply-demand imbalances meet unsustainable groundwater extraction and declining precipitation.</p>

      <div class="legend">
        <div class="legend-item"><div class="legend-box" style="background: var(--accent-danger)"></div> Critical / Overdraft / Extreme Stress</div>
        <div class="legend-item"><div class="legend-box" style="background: var(--accent-warn)"></div> Warning / High Stress</div>
        <div class="legend-item"><div class="legend-box" style="background: var(--accent-safe)"></div> Safe / Low Stress</div>
      </div>
    </header>

    <table>
      <thead>
        <tr>
          <th class="country-col">Country</th>
          <th class="ratio-col">Supply-to-Demand Ratio<br/><span style="font-size: 10px; font-weight: normal">(< 1.0 indicates demand exceeds renewable supply)</span></th>
          <th class="gw-col">Groundwater Extraction / Recharge<br/><span style="font-size: 10px; font-weight: normal">(> 1.0 indicates overdraft)</span></th>
          <th class="pc-col">Freshwater per Capita<br/><span style="font-size: 10px; font-weight: normal">(m³/person/year, log scale)</span></th>
          <th class="precip-col">Precipitation Trend<br/><span style="font-size: 10px; font-weight: normal">(1990s → 2010s, mm/year)</span></th>
        </tr>
      </thead>
      <tbody id="data-rows">
        <!-- Rows will be injected by script -->
      </tbody>
    </table>
  </div>

  <script>
    // Data
    const countries = [
      { name: 'Saudi Arabia', ratio: 0.31, stress: 'Extremely High', gw: 5.66, pc: 84, precip: [98, 89, 78], class: 'eh' },
      { name: 'Egypt', ratio: 0.48, stress: 'Extremely High', gw: 1.63, pc: 570, precip: [52, 47, 41], class: 'eh' },
      { name: 'Pakistan', ratio: 0.65, stress: 'Extremely High', gw: 1.16, pc: 934, precip: [396, 378, 355], class: 'eh' },
      { name: 'India', ratio: 0.72, stress: 'Extremely High', gw: 0.58, pc: 1486, precip: [1120, 1095, 1078], class: 'eh' },
      { name: 'South Africa', ratio: 0.91, stress: 'High', gw: 0.98, pc: 830, precip: [498, 475, 452], class: 'h' },
      { name: 'Mexico', ratio: 1.08, stress: 'High', gw: 0.75, pc: 3656, precip: [758, 742, 725], class: 'h' },
      { name: 'Australia', ratio: 1.55, stress: 'Medium-High', gw: 0.23, pc: 20180, precip: [465, 490, 478], class: 'm' },
      { name: 'United States', ratio: 1.82, stress: 'Medium', gw: 0.88, pc: 8844, precip: [767, 780, 798], class: 'm' },
      { name: 'Brazil', ratio: 4.35, stress: 'Low', gw: 0.1, pc: 27436, precip: [1761, 1748, 1720], class: 'l' },
      { name: 'Canada', ratio: 6.12, stress: 'Low', gw: 0.05, pc: 80620, precip: [537, 548, 562], class: 'l' }
    ];

    const tbody = document.getElementById('data-rows');

    // Max scales
    const maxRatio = 6.5; // for scale 0 to 6.5
    const maxGw = 6.0; // for scale 0 to 6.0
    const logMin = Math.log10(50);
    const logMax = Math.log10(100000);

    countries.forEach(c => {
      const tr = document.createElement('tr');

      // Country
      const tdCountry = document.createElement('td');
      tdCountry.className = 'country-col';
      tdCountry.innerHTML = `<div>${c.name}</div><div class="stress-badge badge-${c.class}">${c.stress}</div>`;
      tr.appendChild(tdCountry);

      // Ratio
      const tdRatio = document.createElement('td');
      tdRatio.className = 'ratio-col';
      const rPct = (c.ratio / maxRatio) * 100;
      const rColor = c.ratio < 1.0 ? 'var(--accent-danger)' : (c.ratio < 2.0 ? 'var(--accent-warn)' : 'var(--accent-safe)');
      tdRatio.innerHTML = `
        <div class="flex-cell">
          <span class="val-text" style="color: ${rColor}">${c.ratio.toFixed(2)}</span>
          <div class="ratio-container">
            <div class="axis-line" style="left: ${(1.0 / maxRatio) * 100}%"></div>
            <div class="ratio-dot" style="left: ${rPct}%; background-color: ${rColor};"></div>
          </div>
        </div>
      `;
      tr.appendChild(tdRatio);

      // Groundwater
      const tdGw = document.createElement('td');
      tdGw.className = 'gw-col';
      const gwPct = (c.gw / maxGw) * 100;
      const gwColor = c.gw > 1.0 ? 'var(--accent-danger)' : (c.gw > 0.8 ? 'var(--accent-warn)' : 'var(--accent-safe)');
      const gwDangerClass = c.gw > 1.0 ? 'gw-danger' : '';
      tdGw.innerHTML = `
        <div class="flex-cell">
          <span class="val-text ${gwDangerClass}">${c.gw.toFixed(2)}</span>
          <div class="gw-container">
            <div class="axis-line" style="left: ${(1.0 / maxGw) * 100}%"></div>
            <div class="gw-bar" style="width: ${gwPct}%; background-color: ${gwColor};"></div>
          </div>
        </div>
      `;
      tr.appendChild(tdGw);

      // Per Capita (Log scale bar)
      const tdPc = document.createElement('td');
      tdPc.className = 'pc-col';
      const logVal = Math.log10(c.pc);
      const pcPct = Math.max(0, (logVal - logMin) / (logMax - logMin) * 100);
      const pcColor = c.pc < 1000 ? 'var(--accent-danger)' : (c.pc < 2000 ? 'var(--accent-warn)' : 'var(--accent-safe)');
      tdPc.innerHTML = `
        <div class="flex-cell">
          <span class="val-text" style="width:55px;">${c.pc.toLocaleString()}</span>
          <div class="bar-chart">
            <div class="bar-fill" style="width: ${pcPct}%; background-color: ${pcColor};"></div>
            <div class="axis-line" style="left: ${ (Math.log10(1000) - logMin)/(logMax-logMin)*100 }%; border-left: 1px dashed var(--accent-danger); background: none; width: 0;"></div>
          </div>
        </div>
      `;
      tr.appendChild(tdPc);

      // Precipitation Sparkline
      const tdPrecip = document.createElement('td');
      tdPrecip.className = 'precip-col';

      // Calculate sparkline points (3 points)
      const maxP = Math.max(...c.precip);
      const minP = Math.min(...c.precip);
      const pDiff = maxP === minP ? 1 : maxP - minP; // avoid division by zero

      const sparkW = 100;
      const sparkH = 20;
      const points = c.precip.map((p, i) => {
        const x = (i / 2) * sparkW;
        const y = sparkH - ((p - minP) / pDiff) * sparkH;
        return `${x},${y}`;
      }).join(' ');

      // Trend color: decreasing = red, increasing = blue
      const trendColor = c.precip[2] < c.precip[0] ? 'var(--accent-danger)' : 'var(--accent-safe)';

      tdPrecip.innerHTML = `
        <div class="flex-cell">
          <svg class="sparkline" viewBox="-2 -2 104 24" preserveAspectRatio="none">
            <polyline points="${points}" stroke="${trendColor}" />
            <circle cx="0" cy="${sparkH - ((c.precip[0] - minP)/pDiff)*sparkH}" r="2" fill="${trendColor}" />
            <circle cx="100" cy="${sparkH - ((c.precip[2] - minP)/pDiff)*sparkH}" r="2" fill="${trendColor}" />
          </svg>
          <span style="font-size: 11px; width: 40px; color: ${trendColor}">${c.precip[2] < c.precip[0] ? '▼' : '▲'}</span>
        </div>
      `;
      tr.appendChild(tdPrecip);

      tbody.appendChild(tr);
    });
  </script>
</body>
</html>
